	private static void vertical7_U16_I8_Div_B4( Kernel1D_S32 kernel,
							   InterleavedU16 src,
							   InterleavedI8 dst,
							   int divisor ) {
		final short[] dataSrc = src.data;
		final byte[] dataDst = dst.data;

		final int k1 = kernel.data[0];
		final int k2 = kernel.data[1];
		final int k3 = kernel.data[2];
		final int k4 = kernel.data[3];
		final int k5 = kernel.data[4];
		final int k6 = kernel.data[5];
		final int k7 = kernel.data[6];

		final int radius = kernel.getRadius();
		final int imgWidth = dst.getWidth();
		final int imgHeight = dst.getHeight();
		final int halfDivisor = divisor/2;
		final int yEnd = imgHeight - radius;

		//CONCURRENT_BELOW BoofConcurrency.loopFor(radius, yEnd, y -> {
		for (int y = radius; y < yEnd; y++) {
			int indexDst = dst.startIndex + y*dst.stride;
			for (int x = 0; x < imgWidth; x++) {
				int indexSrc = src.startIndex + (y - radius)*src.stride + x*4;

				{
					int total = (dataSrc[indexSrc] & 0xFFFF)*k1;
					total += (dataSrc[indexSrc + 1*src.stride] & 0xFFFF)*k2;
					total += (dataSrc[indexSrc + 2*src.stride] & 0xFFFF)*k3;
					total += (dataSrc[indexSrc + 3*src.stride] & 0xFFFF)*k4;
					total += (dataSrc[indexSrc + 4*src.stride] & 0xFFFF)*k5;
					total += (dataSrc[indexSrc + 5*src.stride] & 0xFFFF)*k6;
					total += (dataSrc[indexSrc + 6*src.stride] & 0xFFFF)*k7;
					dataDst[indexDst++] = (byte)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 1] & 0xFFFF)*k1;
					total += (dataSrc[indexSrc + 1*src.stride + 1] & 0xFFFF)*k2;
					total += (dataSrc[indexSrc + 2*src.stride + 1] & 0xFFFF)*k3;
					total += (dataSrc[indexSrc + 3*src.stride + 1] & 0xFFFF)*k4;
					total += (dataSrc[indexSrc + 4*src.stride + 1] & 0xFFFF)*k5;
					total += (dataSrc[indexSrc + 5*src.stride + 1] & 0xFFFF)*k6;
					total += (dataSrc[indexSrc + 6*src.stride + 1] & 0xFFFF)*k7;
					dataDst[indexDst++] = (byte)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 2] & 0xFFFF)*k1;
					total += (dataSrc[indexSrc + 1*src.stride + 2] & 0xFFFF)*k2;
					total += (dataSrc[indexSrc + 2*src.stride + 2] & 0xFFFF)*k3;
					total += (dataSrc[indexSrc + 3*src.stride + 2] & 0xFFFF)*k4;
					total += (dataSrc[indexSrc + 4*src.stride + 2] & 0xFFFF)*k5;
					total += (dataSrc[indexSrc + 5*src.stride + 2] & 0xFFFF)*k6;
					total += (dataSrc[indexSrc + 6*src.stride + 2] & 0xFFFF)*k7;
					dataDst[indexDst++] = (byte)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 3] & 0xFFFF)*k1;
					total += (dataSrc[indexSrc + 1*src.stride + 3] & 0xFFFF)*k2;
					total += (dataSrc[indexSrc + 2*src.stride + 3] & 0xFFFF)*k3;
					total += (dataSrc[indexSrc + 3*src.stride + 3] & 0xFFFF)*k4;
					total += (dataSrc[indexSrc + 4*src.stride + 3] & 0xFFFF)*k5;
					total += (dataSrc[indexSrc + 5*src.stride + 3] & 0xFFFF)*k6;
					total += (dataSrc[indexSrc + 6*src.stride + 3] & 0xFFFF)*k7;
					dataDst[indexDst++] = (byte)((total + halfDivisor)/divisor);
				}
			}
		}
		//CONCURRENT_ABOVE });
	}

	public static boolean horizontal( Kernel1D_S32 kernel, InterleavedS16 src, InterleavedI16 dst ) {
		if (!isSupported(kernel, src, dst))
			return false;

		switch (src.getNumBands()) {
			case 2:
				switch (kernel.width) {
					case 3: horizontal3_S16_I16_B2(kernel, src, dst); break;
					case 5: horizontal5_S16_I16_B2(kernel, src, dst); break;
					case 7: horizontal7_S16_I16_B2(kernel, src, dst); break;
					default: return false;
				}
				break;
			case 3:
				switch (kernel.width) {
					case 3: horizontal3_S16_I16_B3(kernel, src, dst); break;
					case 5: horizontal5_S16_I16_B3(kernel, src, dst); break;
					case 7: horizontal7_S16_I16_B3(kernel, src, dst); break;
					default: return false;
				}
				break;
			case 4:
				switch (kernel.width) {
					case 3: horizontal3_S16_I16_B4(kernel, src, dst); break;
					case 5: horizontal5_S16_I16_B4(kernel, src, dst); break;
					case 7: horizontal7_S16_I16_B4(kernel, src, dst); break;
					default: return false;
				}
				break;
			default: return false;
		}
		return true;
	}

