	public static boolean convolve( Kernel2D_S32 kernel, InterleavedS16 src, InterleavedI16 dst ) {
		if (!isSupported(kernel, src, dst))
			return false;

		switch (src.getNumBands()) {
			case 2:
				switch (kernel.width) {
					case 3: convolve3_S16_I16_B2(kernel, src, dst); break;
					case 5: convolve5_S16_I16_B2(kernel, src, dst); break;
					case 7: convolve7_S16_I16_B2(kernel, src, dst); break;
					default: return false;
				}
				break;
			case 3:
				switch (kernel.width) {
					case 3: convolve3_S16_I16_B3(kernel, src, dst); break;
					case 5: convolve5_S16_I16_B3(kernel, src, dst); break;
					case 7: convolve7_S16_I16_B3(kernel, src, dst); break;
					default: return false;
				}
				break;
			case 4:
				switch (kernel.width) {
					case 3: convolve3_S16_I16_B4(kernel, src, dst); break;
					case 5: convolve5_S16_I16_B4(kernel, src, dst); break;
					case 7: convolve7_S16_I16_B4(kernel, src, dst); break;
					default: return false;
				}
				break;
			default: return false;
		}
		return true;
	}

	private static void horizontal3_S16_I16_B2( Kernel1D_S32 kernel,
							   InterleavedS16 src,
							   InterleavedI16 dst ) {
		final short[] dataSrc = src.data;
		final short[] dataDst = dst.data;

		final int k1 = kernel.data[0];
		final int k2 = kernel.data[1];
		final int k3 = kernel.data[2];

		final int radius = kernel.getRadius();
		final int imgWidth = src.getWidth();

		//CONCURRENT_BELOW BoofConcurrency.loopFor(0, src.height, y -> {
		for (int y = 0; y < src.height; y++) {
			int indexDst = dst.startIndex + y*dst.stride + radius*2;
			for (int x = radius; x < imgWidth - radius; x++) {
				int indexSrc = src.startIndex + y*src.stride + (x - radius)*2;

				{
					int total = (dataSrc[indexSrc])*k1;
					total += (dataSrc[indexSrc + 2])*k2;
					total += (dataSrc[indexSrc + 4])*k3;
					dataDst[indexDst++] = (short)total;
				}

				{
					int total = (dataSrc[indexSrc + 1])*k1;
					total += (dataSrc[indexSrc + 3])*k2;
					total += (dataSrc[indexSrc + 5])*k3;
					dataDst[indexDst++] = (short)total;
				}
			}
		}
		//CONCURRENT_ABOVE });
	}

