	private static void horizontal3_U8_I8_Div_B2( Kernel1D_S32 kernel,
							   InterleavedU8 src,
							   InterleavedI8 dst,
							   int divisor ) {
		final byte[] dataSrc = src.data;
		final byte[] dataDst = dst.data;

		final int k1 = kernel.data[0];
		final int k2 = kernel.data[1];
		final int k3 = kernel.data[2];

		final int radius = kernel.getRadius();
		final int imgWidth = src.getWidth();
		final int halfDivisor = divisor/2;

		//CONCURRENT_BELOW BoofConcurrency.loopFor(0, src.height, y -> {
		for (int y = 0; y < src.height; y++) {
			int indexDst = dst.startIndex + y*dst.stride + radius*2;
			for (int x = radius; x < imgWidth - radius; x++) {
				int indexSrc = src.startIndex + y*src.stride + (x - radius)*2;

				{
					int total = (dataSrc[indexSrc] & 0xFF)*k1;
					total += (dataSrc[indexSrc + 2] & 0xFF)*k2;
					total += (dataSrc[indexSrc + 4] & 0xFF)*k3;
					dataDst[indexDst++] = (byte)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 1] & 0xFF)*k1;
					total += (dataSrc[indexSrc + 3] & 0xFF)*k2;
					total += (dataSrc[indexSrc + 5] & 0xFF)*k3;
					dataDst[indexDst++] = (byte)((total + halfDivisor)/divisor);
				}
			}
		}
		//CONCURRENT_ABOVE });
	}

