	public static boolean convolve( Kernel2D_S32 kernel, InterleavedS16 src, InterleavedI16 dst, int divisor ) {
		if (!isSupported(kernel, src, dst))
			return false;

		switch (src.getNumBands()) {
			case 2:
				switch (kernel.width) {
					case 3: convolve3_S16_I16_Div_B2(kernel, src, dst, divisor); break;
					case 5: convolve5_S16_I16_Div_B2(kernel, src, dst, divisor); break;
					case 7: convolve7_S16_I16_Div_B2(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			case 3:
				switch (kernel.width) {
					case 3: convolve3_S16_I16_Div_B3(kernel, src, dst, divisor); break;
					case 5: convolve5_S16_I16_Div_B3(kernel, src, dst, divisor); break;
					case 7: convolve7_S16_I16_Div_B3(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			case 4:
				switch (kernel.width) {
					case 3: convolve3_S16_I16_Div_B4(kernel, src, dst, divisor); break;
					case 5: convolve5_S16_I16_Div_B4(kernel, src, dst, divisor); break;
					case 7: convolve7_S16_I16_Div_B4(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			default: return false;
		}
		return true;
	}

	private static void horizontal3_S16_I16_Div_B2( Kernel1D_S32 kernel,
							   InterleavedS16 src,
							   InterleavedI16 dst,
							   int divisor ) {
		final short[] dataSrc = src.data;
		final short[] dataDst = dst.data;

		final int k1 = kernel.data[0];
		final int k2 = kernel.data[1];
		final int k3 = kernel.data[2];

		final int radius = kernel.getRadius();
		final int imgWidth = src.getWidth();
		final int halfDivisor = divisor/2;

		//CONCURRENT_BELOW BoofConcurrency.loopFor(0, src.height, y -> {
		for (int y = 0; y < src.height; y++) {
			int indexDst = dst.startIndex + y*dst.stride + radius*2;
			for (int x = radius; x < imgWidth - radius; x++) {
				int indexSrc = src.startIndex + y*src.stride + (x - radius)*2;

				{
					int total = (dataSrc[indexSrc])*k1;
					total += (dataSrc[indexSrc + 2])*k2;
					total += (dataSrc[indexSrc + 4])*k3;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 1])*k1;
					total += (dataSrc[indexSrc + 3])*k2;
					total += (dataSrc[indexSrc + 5])*k3;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}
			}
		}
		//CONCURRENT_ABOVE });
	}

	private static void vertical3_S16_I16_Div_B2( Kernel1D_S32 kernel,
							   InterleavedS16 src,
							   InterleavedI16 dst,
							   int divisor ) {
		final short[] dataSrc = src.data;
		final short[] dataDst = dst.data;

		final int k1 = kernel.data[0];
		final int k2 = kernel.data[1];
		final int k3 = kernel.data[2];

		final int radius = kernel.getRadius();
		final int imgWidth = dst.getWidth();
		final int imgHeight = dst.getHeight();
		final int halfDivisor = divisor/2;
		final int yEnd = imgHeight - radius;

		//CONCURRENT_BELOW BoofConcurrency.loopFor(radius, yEnd, y -> {
		for (int y = radius; y < yEnd; y++) {
			int indexDst = dst.startIndex + y*dst.stride;
			for (int x = 0; x < imgWidth; x++) {
				int indexSrc = src.startIndex + (y - radius)*src.stride + x*2;

				{
					int total = (dataSrc[indexSrc])*k1;
					total += (dataSrc[indexSrc + 1*src.stride])*k2;
					total += (dataSrc[indexSrc + 2*src.stride])*k3;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 1])*k1;
					total += (dataSrc[indexSrc + 1*src.stride + 1])*k2;
					total += (dataSrc[indexSrc + 2*src.stride + 1])*k3;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}
			}
		}
		//CONCURRENT_ABOVE });
	}

	private static void convolve3_S16_I16_Div_B2( Kernel2D_S32 kernel,
							   InterleavedS16 src,
							   InterleavedI16 dst,
							   int divisor ) {
		final short[] dataSrc = src.data;
		final short[] dataDst = dst.data;

		final int k1 = kernel.data[0];
		final int k2 = kernel.data[1];
		final int k3 = kernel.data[2];
		final int k4 = kernel.data[3];
		final int k5 = kernel.data[4];
		final int k6 = kernel.data[5];
		final int k7 = kernel.data[6];
		final int k8 = kernel.data[7];
		final int k9 = kernel.data[8];

		final int imgWidth = src.getWidth();
		final int imgHeight = src.getHeight();
		final int radius = kernel.getRadius();
		final int halfDivisor = divisor/2;
		final int yEnd = imgHeight - radius;

		//CONCURRENT_BELOW BoofConcurrency.loopFor(radius, yEnd, y -> {
		for (int y = radius; y < yEnd; y++) {
			int indexDst = dst.startIndex + y*dst.stride + radius*2;
			for (int x = radius; x < imgWidth - radius; x++) {
				int indexSrc = src.startIndex + (y - radius)*src.stride + (x - radius)*2;

				{
					int total = (dataSrc[indexSrc])*k1;
					total += (dataSrc[indexSrc + 2])*k2;
					total += (dataSrc[indexSrc + 4])*k3;
					total += (dataSrc[indexSrc + 1*src.stride])*k4;
					total += (dataSrc[indexSrc + 1*src.stride + 2])*k5;
					total += (dataSrc[indexSrc + 1*src.stride + 4])*k6;
					total += (dataSrc[indexSrc + 2*src.stride])*k7;
					total += (dataSrc[indexSrc + 2*src.stride + 2])*k8;
					total += (dataSrc[indexSrc + 2*src.stride + 4])*k9;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 1])*k1;
					total += (dataSrc[indexSrc + 3])*k2;
					total += (dataSrc[indexSrc + 5])*k3;
					total += (dataSrc[indexSrc + 1*src.stride + 1])*k4;
					total += (dataSrc[indexSrc + 1*src.stride + 3])*k5;
					total += (dataSrc[indexSrc + 1*src.stride + 5])*k6;
					total += (dataSrc[indexSrc + 2*src.stride + 1])*k7;
					total += (dataSrc[indexSrc + 2*src.stride + 3])*k8;
					total += (dataSrc[indexSrc + 2*src.stride + 5])*k9;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}
			}
		}
		//CONCURRENT_ABOVE });
	}

