	public static boolean vertical( Kernel1D_S32 kernel, InterleavedS32 src, InterleavedI16 dst, int divisor ) {
		if (!isSupported(kernel, src, dst))
			return false;

		switch (src.getNumBands()) {
			case 2:
				switch (kernel.width) {
					case 3: vertical3_S32_I16_Div_B2(kernel, src, dst, divisor); break;
					case 5: vertical5_S32_I16_Div_B2(kernel, src, dst, divisor); break;
					case 7: vertical7_S32_I16_Div_B2(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			case 3:
				switch (kernel.width) {
					case 3: vertical3_S32_I16_Div_B3(kernel, src, dst, divisor); break;
					case 5: vertical5_S32_I16_Div_B3(kernel, src, dst, divisor); break;
					case 7: vertical7_S32_I16_Div_B3(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			case 4:
				switch (kernel.width) {
					case 3: vertical3_S32_I16_Div_B4(kernel, src, dst, divisor); break;
					case 5: vertical5_S32_I16_Div_B4(kernel, src, dst, divisor); break;
					case 7: vertical7_S32_I16_Div_B4(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			default: return false;
		}
		return true;
	}

	private static void vertical3_S32_I16_Div_B2( Kernel1D_S32 kernel,
							   InterleavedS32 src,
							   InterleavedI16 dst,
							   int divisor ) {
		final int[] dataSrc = src.data;
		final short[] dataDst = dst.data;

		final int k1 = kernel.data[0];
		final int k2 = kernel.data[1];
		final int k3 = kernel.data[2];

		final int radius = kernel.getRadius();
		final int imgWidth = dst.getWidth();
		final int imgHeight = dst.getHeight();
		final int halfDivisor = divisor/2;
		final int yEnd = imgHeight - radius;

		//CONCURRENT_BELOW BoofConcurrency.loopFor(radius, yEnd, y -> {
		for (int y = radius; y < yEnd; y++) {
			int indexDst = dst.startIndex + y*dst.stride;
			for (int x = 0; x < imgWidth; x++) {
				int indexSrc = src.startIndex + (y - radius)*src.stride + x*2;

				{
					int total = (dataSrc[indexSrc])*k1;
					total += (dataSrc[indexSrc + 1*src.stride])*k2;
					total += (dataSrc[indexSrc + 2*src.stride])*k3;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}

				{
					int total = (dataSrc[indexSrc + 1])*k1;
					total += (dataSrc[indexSrc + 1*src.stride + 1])*k2;
					total += (dataSrc[indexSrc + 2*src.stride + 1])*k3;
					dataDst[indexDst++] = (short)((total + halfDivisor)/divisor);
				}
			}
		}
		//CONCURRENT_ABOVE });
	}

