	public static boolean horizontal( Kernel1D_S32 kernel, InterleavedS32 src, InterleavedS32 dst ) {
		if (!isSupported(kernel, src, dst))
			return false;

		switch (src.getNumBands()) {
			case 2:
				switch (kernel.width) {
					case 3: horizontal3_S32_S32_B2(kernel, src, dst); break;
					case 5: horizontal5_S32_S32_B2(kernel, src, dst); break;
					case 7: horizontal7_S32_S32_B2(kernel, src, dst); break;
					default: return false;
				}
				break;
			case 3:
				switch (kernel.width) {
					case 3: horizontal3_S32_S32_B3(kernel, src, dst); break;
					case 5: horizontal5_S32_S32_B3(kernel, src, dst); break;
					case 7: horizontal7_S32_S32_B3(kernel, src, dst); break;
					default: return false;
				}
				break;
			case 4:
				switch (kernel.width) {
					case 3: horizontal3_S32_S32_B4(kernel, src, dst); break;
					case 5: horizontal5_S32_S32_B4(kernel, src, dst); break;
					case 7: horizontal7_S32_S32_B4(kernel, src, dst); break;
					default: return false;
				}
				break;
			default: return false;
		}
		return true;
	}

