	public static boolean horizontal( Kernel1D_S32 kernel, InterleavedS32 src, InterleavedS32 dst, int divisor ) {
		if (!isSupported(kernel, src, dst))
			return false;

		switch (src.getNumBands()) {
			case 2:
				switch (kernel.width) {
					case 3: horizontal3_S32_S32_Div_B2(kernel, src, dst, divisor); break;
					case 5: horizontal5_S32_S32_Div_B2(kernel, src, dst, divisor); break;
					case 7: horizontal7_S32_S32_Div_B2(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			case 3:
				switch (kernel.width) {
					case 3: horizontal3_S32_S32_Div_B3(kernel, src, dst, divisor); break;
					case 5: horizontal5_S32_S32_Div_B3(kernel, src, dst, divisor); break;
					case 7: horizontal7_S32_S32_Div_B3(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			case 4:
				switch (kernel.width) {
					case 3: horizontal3_S32_S32_Div_B4(kernel, src, dst, divisor); break;
					case 5: horizontal5_S32_S32_Div_B4(kernel, src, dst, divisor); break;
					case 7: horizontal7_S32_S32_Div_B4(kernel, src, dst, divisor); break;
					default: return false;
				}
				break;
			default: return false;
		}
		return true;
	}

